package lib
type T struct { Wrong bool }
type Item struct{}
type Box[X any] struct { Value X }
type Erase[X any] = int
type Drop[A, B any] = []A
func Identity[T any](value T) T { return value }
func Make[T any]() T { var zero T; return zero }
func Pair[A, B any](left A) B { var zero B; return zero }
func Slice[S ~[]E, E any](values S) S { return values }
func Erased[T any](value Erase[T]) int { return value }
func Select[A, B any](value Drop[A, B]) A { return value[0] }
func Boxed[T any](value Box[T]) T { return value.Value }
func Nested[T any](cb func(T int) T, value T) T { return cb(1) }
func Concrete[T any](value T, other Item) Box[T] { return Box[T]{Value: value} }
type KeepGlobal[X any] = []T
func Hidden[T any](value KeepGlobal[T]) int { return len(value) }

